  ('higher-math-board-chattogram-2023-mcq-024', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p34', '△ P QR এর মধ্যমাত্রার পরস্পরকে O বিন্দুতে ছেদ করলে, O বিন্দুকে বলা হয় —', 'mcq', '{"ক":"লম্ববিন্দু","খ":"পরিকেন্দ্র","গ":"ভরকেন্দ্র","ঘ":"শীর্ষবিন্দু"}'::jsonb, 'গ', 1, false, 'higher-math-board-chattogram-2023-mcq', false, 'board-mcq', null, null, 'chattogram', 2023, true),
  ('higher-math-board-chattogram-2023-mcq-025', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p34', '1.85 এর মূলদীয় ভগ্নাংশ নিচের কোনটি?', 'mcq', '{"ক":"37 20","খ":"167 90","গ":"184 99","ঘ":"167 900"}'::jsonb, 'খ', 1, false, 'higher-math-board-chattogram-2023-mcq', false, 'board-mcq', null, null, 'chattogram', 2023, true),
  ('higher-math-board-chattogram-2024-mcq-001', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p13', 'একটি ত্রিভুজ গঠন করা যায় যখন- i. ভূমি, ভূমি সংলগ্ন একটি কোণ এবং উচ্চতা দেওয়া থাকলে ii. ভূমি, শিরঃকোণ এবং অপর দুই বাহুর সমষ্টি দেওয়া থাকলে iii. ভূমি সংলগ্ন একটি কোণ, উচ্চতা এবং অপর দুই বাহুর সমষ্টি দেওয়া থাকলে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-002', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p13', 'একই ভূমির উপর এবং একই উচ্চতাবিশিষ্ট একটি সমবৃত্তভূমিক কোণক ও একটি সিলিন্ডারের আয়তনের অনুপাত কোনটি?', 'mcq', '{"ক":"1:3","খ":"3:1","গ":"1:2","ঘ":"1:1"}'::jsonb, 'ক', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-003', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p13', 'কোনটির জন্য 2x – 3y < 6 সঠিক?', 'mcq', '{"ক":"(2, 0)","খ":"(3,0)","গ":"(5, 1)","ঘ":"(1,-2)"}'::jsonb, 'ক', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-004', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p13', 'logx4 + logx16= 6 হলে, logx 8 এর মান কত?', 'mcq', '{"ক":"1","খ":"2","গ":"3","ঘ":"6"}'::jsonb, 'গ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-005', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p13', '3(1-2x) (3x+2) এর মুখ্য সহগ কত?', 'mcq', '{"ক":"-18","খ":"-6","গ":"6","ঘ":"18"}'::jsonb, 'ক', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-006', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p13', '-3380° কোণটির অবস্থান কোন চতু র্ভাগে?', 'mcq', '{"ক":"প্রথম","খ":"দ্বিতীয়","গ":"তৃ তীয়","ঘ":"চতু র্থ"}'::jsonb, 'গ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-007', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p13', 'HIGHER MATHEMATICS শব্দটির অক্ষরগুলো পৃথকভাবে একটি বাক্সে রাখা আছে। দৈবভাবে একটি বর্ণ তোলা হলো। বর্ণটি A অথবা H না হওয়ার সম্ভাবনা কত?', 'mcq', '{"ক":"2 17","খ":"3 17","গ":"5 17","ঘ":"12 17"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-008', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p13', 'একটি অনুক্রমের n-তম পদ U n = 1− ( −1 ) n অনুক্রমটির প্রথম 12 টি ও প্রথম 6 টি পদের সমষ্টির পার্থক্য কত? 2', 'mcq', '{"ক":"","খ":"1","গ":"3","ঘ":"6"}'::jsonb, 'গ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', 'অপশন চিহ্ন পাওয়া যায়নি: ক (ছাপায় নেই বা চিত্র আকারে); ক অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে)', null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-009', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p13', '∫ (x)= 5 −x হলে- i. ডোম ∫ =(−∞, ∞) ii. ∫ =(0, ∞) iii. ∫ 1 (x)= −1. 43 log x নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-010', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p14', 'যদি x>y>0 এবং z<0 হয়, তবে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"x y x y < > z z z z","খ":"z y < x z","গ":"","ঘ":"z y > x z"}'::jsonb, 'ক', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', 'গ অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে)', null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-011', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p14', 'tan θ = 5 12 এবং π < θ < 3π 2 হলে, cosθ এর মান কত?', 'mcq', '{"ক":"13 12","খ":"5 13","গ":"−12 13","ঘ":"− 5 13"}'::jsonb, 'গ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-012', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p14', 'ΔABC − এ sec ( A+B )=? 2', 'mcq', '{"ক":"cos ec π 2","খ":"sec π 2","গ":"sec c 2","ঘ":"cosec c 2"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-013', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p14', '∆ABC এ BC=p, CA=q, AB = r এবং p2>q2+r2 হলে', 'mcq', '{"ক":"∠A সূক্ষ্মকোণ","খ":"∠A স্থূলকোণ","গ":"∠C স্থূলকোণ","ঘ":"∠B স্থূলকোণ"}'::jsonb, 'খ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-014', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p14', '∆ DEF এর ক্ষেত্রে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"− −→ − −→ − −→ DE + EF = F D","খ":"− −→ − −→ − −→ DE + DF = EF","গ":"− −→ − −→ − −→ F E + ED + F D = 0","ঘ":"− −→ − −→ − −→ DE + EF + F D = 0"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-015', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p14', 'tan ( nπ + θ)= − 1 এবং θ = π হলে, n এর মান কত? 2 √3 3', 'mcq', '{"ক":"− 1 3","খ":"− 7 3","গ":"5 3","ঘ":"1"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-016', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p14', '(1-ax)6 এর বিস্তৃতিতে x3 এবং x4 এর সহগ পরস্পর সমান হলে, a এর মান কত?', 'mcq', '{"ক":"4 3","খ":"3 4","গ":"− 3 4","ঘ":"− 4 3"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-017', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p14', '√3x + y − 5 = 0 রেখাটি x-অক্ষের ধনাত্মক দিকের সাথে উৎপন্ন কোণের পরিমাণ কত?', 'mcq', '{"ক":"30°","খ":"60°","গ":"120°","ঘ":"150°"}'::jsonb, 'গ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-018', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p14', 'সার্বিক সেট U এর উপসেট A, B এবং C হলে- i. (A∪ B)'' = A''∩B'' ii. (A∩B)=A''∩B'' iii. AU(B∩C) = (AUB)∩(AUC) নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-019', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p14', 'যদি F(x) = px2 + qx+r এবং p+q+r=0 হয়, তবে F(x) এর একটি উৎপাদক কোনটি?', 'mcq', '{"ক":"x-p","খ":"x-q","গ":"x-2","ঘ":"x-1"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-020', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p14', '∆AOB এর ক্ষেত্রফল কত বর্গ একক?', 'mcq', '{"ক":"3","খ":"6","গ":"7","ঘ":"12"}'::jsonb, 'খ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-021', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p14', 'নিচের কোনটি AB রেখার সমীকরণ?', 'mcq', '{"ক":"3x-4y-12=0","খ":"3x+4y-12=0","গ":"3x-4y + 12 = 0","ঘ":"3x+4y+12=0"}'::jsonb, 'খ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, null, 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-022', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p15', 'নিশ্চায়ক = 0 হলে, P এর মান কত?', 'mcq', '{"ক":"9 2","খ":"2 9","গ":"− 2 9","ঘ":"− 9 2"}'::jsonb, 'ক', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, 'Px2-18x+18= 0 একটি দ্বিঘাত সমীকরণ।', 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-023', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p15', 'P = 1 9 হলে, সমীকরণটির মূলদ্বয়ের ধরন ও প্রকৃতি কীরূপ?', 'mcq', '{"ক":"মূলদ ও সমান","খ":"মূলদ ও অসমান","গ":"অমূলদ ও সমান","ঘ":"অমূলদ ও অসমান"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, 'Px2-18x+18= 0 একটি দ্বিঘাত সমীকরণ।', 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-024', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p15', 'BC এর উপর AP ও AC এর লম্ব অভিক্ষেপের দৈর্ঘ্যের সমষ্টি কত সে. মি?', 'mcq', '{"ক":"8","খ":"16","গ":"24","ঘ":"32"}'::jsonb, 'গ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, 'চিত্রে BC ও AB এর মধ্যবিন্দু যথাক্রমে P ও M. BP = BM = 8 সে. মি.', 'chattogram', 2024, true),
  ('higher-math-board-chattogram-2024-mcq-025', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p15', 'AP + CM = কত সে. মি.?', 'mcq', '{"ক":"8√5","খ":"16√5","গ":"24√5","ঘ":"32√5"}'::jsonb, 'খ', 1, false, 'higher-math-board-chattogram-2024-mcq', false, 'board-mcq', null, 'চিত্রে BC ও AB এর মধ্যবিন্দু যথাক্রমে P ও M. BP = BM = 8 সে. মি.', 'chattogram', 2024, true),
  ('higher-math-board-cumilla-2023-mcq-001', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p26', '△ ABC ত্রিভুজের বাহুগুলোর বর্গের সমষ্টি কত সে.মি.?', 'mcq', '{"ক":"66.67 সে.মি. (প্রায়)","খ":"60.76 সে.মি. (প্রায়)","গ":"37.50 সে.মি. (প্রায়)","ঘ":"33.33 সে.মি. (প্রায়)"}'::jsonb, 'ক', 1, false, 'higher-math-board-cumilla-2023-mcq', false, 'board-mcq', null, null, 'cumilla', 2023, true),
  ('higher-math-board-cumilla-2023-mcq-002', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p27', 'BP এর দৈর্ঘ্য কত সে.মি.?', 'mcq', '{"ক":"4 3 সে.মি.","খ":"4 2 সে.মি.","গ":"8 3 সে.মি.","ঘ":"10 3 সে.মি. (4x2+4x+1)2 ও এর বিস্তৃতিতে পদসংখ্যা 7"}'::jsonb, 'গ', 1, false, 'higher-math-board-cumilla-2023-mcq', false, 'board-mcq', null, null, 'cumilla', 2023, true),
  ('higher-math-board-cumilla-2023-mcq-003', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p27', 'বিস্তৃতির চতু র্থ পদ কত?', 'mcq', '{"ক":"160x 3","খ":"160x 2","গ":"60x 3","ঘ":"60x 2"}'::jsonb, 'ক', 1, false, 'higher-math-board-cumilla-2023-mcq', false, 'board-mcq', null, null, 'cumilla', 2023, true),
