  ('higher-math-board-cumilla-2023-mcq-005', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p27', '2 সে.মি. ব্যাসার্ধবিশিষ্ট বৃত্তের একটি চাপ কেন্দ্রে 90° কোণ উৎপন্ন করলে চাপের দৈর্ঘ্য কত সে.মি. হবে?', 'mcq', '{"ক":"π সে.মি.","খ":"3π 2 সে.মি.","গ":"2π সে.মি.","ঘ":"4 π সে.মি."}'::jsonb, 'ক', 1, false, 'higher-math-board-cumilla-2023-mcq', false, 'board-mcq', null, null, 'cumilla', 2023, true),
